// ==UserScript==
// @name         Spotify Last.fm Puppeteer
// @namespace    https://github.com/
// @version      2.0
// @description  Puppeteer Spotify's search UI to perform actions launched from Last.fm
// @match        https://open.spotify.com/search/*
// @grant        none
// ==/UserScript==

// AUTO-GENERATED from src/spotify-puppeteer/. Do not edit this file directly.
// Edit the module files under src/spotify-puppeteer/ and re-run scripts/build.sh.

(function () {
    'use strict';

    const LOG_PREFIX = "[lastfm→spotify]";

    const log = (...args)=>
        console.log(LOG_PREFIX, ...args);


    // ---------- config bridge ----------

    // When running as the Chrome extension, content/bridge.js populates
    // window.__LFS_CONFIG. Under Tampermonkey it's absent and getConfig()
    // returns defaults, preserving the original behaviour.

    const CONFIG_DEFAULTS = {
        autoClose: true,
    };

    function getConfig(){
        const bridged =
            (typeof window !== "undefined" && window.__LFS_CONFIG) || null;
        return bridged
            ? Object.assign({}, CONFIG_DEFAULTS, bridged)
            : CONFIG_DEFAULTS;
    }


    const params =
        new URLSearchParams(
            window.location.search
        );


    if (!params.has("lastfm")) {

        log("Normal Spotify search - ignoring");

        return;
    }


    const action =
        params.get("action") || "play";


    // Reassigned per batch item in SPA-navigation mode (the batch
    // carries an entity per item); starts from the load-time param.
    let entity =
        params.get("entity") || "track";


    log("action:", action, "entity:", entity);


    const TIMEOUT_MS   = 30000;
    const CLOSE_MS     = 1000;
    const MENU_WAIT_MS = 2500;

    // SPA fast-path tuning: how long to wait for in-app search results
    // to reflect a navigator.push before falling back to a full reload,
    // and a courtesy pause between SPA hops so the previous action's
    // request has fired.
    const SPA_NAV_TIMEOUT_MS = 4000;
    const SPA_HOP_DELAY_MS   = 300;

    // ---------- utils ----------

    const delay = ms => new Promise(r => setTimeout(r, ms));


    // SPA navigation fast-path. Spotify's web player is a React-Router
    // app; reloading the whole page per batch item costs ~2.2s each,
    // while an in-app route change updates results in ~0.6s. We reach
    // the router's history object ("navigator") by walking the React
    // fiber tree for the NavigationContext value, then push new search
    // routes without a reload. Everything here is best-effort — any
    // failure falls back to full-reload navigation, so a Spotify
    // internals change degrades to the old (slower) behaviour rather
    // than breaking.

    let cachedNavigator; // undefined = not looked up yet, null = absent

    function findSpotifyNavigator(){

        if(cachedNavigator !== undefined) return cachedNavigator;

        cachedNavigator = null;

        try {

            let rootEl = null, fiberKey = null;

            for(const el of document.querySelectorAll("div, main, body")){
                const k = Object.keys(el).find(k =>
                    k.startsWith("__reactFiber$") ||
                    k.startsWith("__reactContainer$"));
                if(k){ rootEl = el; fiberKey = k; break; }
            }

            if(!rootEl) return null;


            const seen  = new Set();
            const stack = [rootEl[fiberKey]];
            let visited = 0;

            while(stack.length && visited < 20000){

                const f = stack.pop();
                visited++;

                if(!f || seen.has(f)) continue;
                seen.add(f);

                const v = f.memoizedProps && f.memoizedProps.value;

                if(v && typeof v === "object"){
                    if(v.navigator &&
                       typeof v.navigator.push === "function" &&
                       typeof v.navigator.createHref === "function"){
                        cachedNavigator = v.navigator;
                        break;
                    }
                    if(typeof v.push === "function" &&
                       typeof v.createHref === "function" &&
                       typeof v.listen === "function"){
                        cachedNavigator = v;
                        break;
                    }
                }

                if(f.child)   stack.push(f.child);
                if(f.sibling) stack.push(f.sibling);

            }

        } catch (_) {
            cachedNavigator = null;
        }

        return cachedNavigator;

    }


    // Signature of the current top result — used to detect when an
    // in-app search has actually re-rendered after a route push.
    function firstResultHref(){
        const root = mainRoot();
        const a = root.querySelector(
            'a[href*="/track/"], a[href*="/album/"], a[href*="/artist/"]'
        );
        return a ? a.getAttribute("href") : null;
    }


    // Push a new /search/{q} route via the router and wait for the
    // results to change. Returns false if the push throws or results
    // don't update in time, so the caller can fall back to a reload.
    async function spaGotoSearch(nav, item){

        const before = firstResultHref();

        try {
            nav.push("/search/" + encodeURIComponent(item.q));
        } catch (_) {
            return false;
        }

        const t0 = Date.now();

        while(Date.now() - t0 < SPA_NAV_TIMEOUT_MS){
            await delay(100);
            const href = firstResultHref();
            if(href && href !== before) return true;
        }

        return false;

    }


    // Resolve when `check()` returns a truthy value, using a MutationObserver
    // over document.body. Rejects after `timeoutMs` if nothing matches.

    function waitFor(check, timeoutMs){

        return new Promise((resolve, reject)=>{


            const immediate = check();

            if(immediate){
                resolve(immediate);
                return;
            }


            const observer =
                new MutationObserver(()=>{

                    const v = check();

                    if(v){
                        observer.disconnect();
                        clearTimeout(timer);
                        resolve(v);
                    }

                });


            observer.observe(
                document.body,
                {
                    childList:true,
                    subtree:true,
                    attributes:true
                }
            );


            const timer =
                setTimeout(()=>{

                    observer.disconnect();

                    reject(
                        new Error("timeout")
                    );

                }, timeoutMs);

        });

    }



    function closeHelper(){

        if (!getConfig().autoClose) {
            log("autoClose disabled — leaving helper tab open");
            return;
        }

        setTimeout(()=>{

            // Extension path: window.close() is blocked on tabs opened
            // via chrome.tabs.create (the browser only allows close on
            // windows opened by window.open()). Route through the
            // service worker's chrome.tabs.remove instead.
            //
            // Under Tampermonkey chrome.runtime.id is undefined and we
            // fall back to window.close(), which works because
            // GM_openInTab establishes a real opener relationship.

            if (typeof chrome !== "undefined" &&
                chrome.runtime &&
                chrome.runtime.id) {

                chrome.runtime.sendMessage({ type: "closeTab" });
                return;

            }

            window.close();

        }, CLOSE_MS);

    }


    // Batch mode: the Last.fm side can queue multiple items into a
    // single helper tab by encoding a JSON array of {q, entity} pairs
    // in the ?batch= param. After each successful (or failed) action
    // we navigate the same tab to the next item's search URL instead
    // of closing, and only close when the batch is exhausted.

    function parseBatch(){

        const raw = params.get("batch");

        if(!raw) return null;


        try {
            const parsed = JSON.parse(raw);
            return Array.isArray(parsed) ? parsed : null;
        } catch (_) {
            return null;
        }

    }


    function navigateNext(remaining){

        const next = remaining[0];

        const nextParams = new URLSearchParams();

        nextParams.set("lastfm", "true");
        nextParams.set("action",  action);
        nextParams.set("entity",  next.entity || "track");
        nextParams.set("batch",   JSON.stringify(remaining));


        setTimeout(()=>{

            window.location.href =
                "/search/" +
                encodeURIComponent(next.q) +
                "?" + nextParams.toString();

        }, CLOSE_MS);

    }


    // Called once at the end of run(). In batch mode, advances to the
    // next item (even on failure — one flaky track shouldn't stall the
    // whole batch). In single mode, closes on success and leaves the
    // tab open on failure (visible signal that something went wrong).

    function finish(success){

        const batch = parseBatch();

        if(batch && batch.length > 1){
            navigateNext(batch.slice(1));
            return;
        }

        if(success)
            closeHelper();

    }



    // Try each strategy in order until one returns a truthy value.
    // Only logs when we fall past the primary strategy — that's the
    // signal that Spotify has changed something and the top selector
    // may need updating.

    function resolveWith(label, strategies, ...args){


        for(let i = 0; i < strategies.length; i++){

            const { name, run } = strategies[i];


            let result;

            try {
                result = run(...args);
            } catch (e) {
                log(`${label} strategy "${name}" threw:`, e);
                continue;
            }


            if(result){

                if(i > 0)
                    log(`${label} matched via fallback "${name}"`);

                return result;

            }

        }


        log(`${label}: no strategy matched`);

        return null;

    }




    // ---------- result finding ----------

    // The Last.fm side always sends us to /search/{q}. We disambiguate
    // by the requested entity's URL fragment (/track/, /album/, /artist/)
    // since Spotify's URL scheme is far more stable than any data-testid
    // or CSS class.

    function entityHrefFragment(){

        return (
            entity === "album"  ? "/album/"  :
            entity === "artist" ? "/artist/" :
            "/track/"
        );

    }


    function mainRoot(){

        return document.querySelector("main") || document.body;

    }


    const rowStrategies = [

        // Primary: list-row shape used on /search/{q}.
        {
            name: "role=row + data-testid=title link",
            run: ()=>{

                const frag = entityHrefFragment();

                for(const row of document.querySelectorAll('[role="row"]')){

                    if(row.querySelector(
                        `[data-testid="title"] a[href*="${frag}"]`
                    ))
                        return row;

                }

                return null;

            }
        },


        // Defensive: tracklist-row shape used on /search/{q}/tracks.
        {
            name: "data-testid=tracklist-row + track link",
            run: ()=>{

                if(entity !== "track")
                    return null;


                for(const row of document.querySelectorAll(
                    '[data-testid="tracklist-row"]'
                )){

                    if(row.querySelector('a[href*="/track/"]'))
                        return row;

                }

                return null;

            }
        },


        // Structural: first entity link inside <main>, walked up to the
        // nearest container that also has an actionable button. Survives
        // arbitrary role/testid renames as long as Spotify still uses
        // /track/, /album/, /artist/ URLs and puts a play/more/save
        // button beside the title.
        {
            name: "structural walk from first main-content entity link",
            run: ()=>{

                const frag = entityHrefFragment();
                const root = mainRoot();


                const link =
                    root.querySelector(`a[href*="${frag}"]`);


                if(!link) return null;


                let el = link;


                while(el && el !== root){

                    if(el.getAttribute("role") === "row")
                        return el;


                    if(el.querySelector(
                        'button[data-testid="play-button"], ' +
                        'button[data-testid="more-button"], ' +
                        'button[aria-haspopup="menu"], ' +
                        'button[aria-label^="Play "]'
                    ))
                        return el;


                    el = el.parentElement;

                }


                return link.closest(
                    '[role="row"], article, [role="group"]'
                ) || link.parentElement;

            }
        }

    ];


    function findRow(){

        return resolveWith("findRow", rowStrategies);

    }




    // ---------- actions ----------

    const playStrategies = [

        {
            name: "data-testid=play-button",
            run: row => row.querySelector(
                'button[data-testid="play-button"]'
            )
        },

        {
            name: 'aria-label ^= "Play "',
            run: row => row.querySelector(
                'button[aria-label^="Play "], button[aria-label="Play"]'
            )
        },

        // Structural fallback: primary Encore button inside the row that
        // isn't the "more options" menu button.
        {
            name: "first primary/tertiary button that isn't more/save",
            run: row => {

                const buttons =
                    [...row.querySelectorAll("button")];


                return buttons.find(b =>
                    !b.hasAttribute("aria-haspopup") &&
                    !/more|options|save|liked|library/i
                        .test(b.getAttribute("aria-label") || "")
                );

            }
        }

    ];


    function doPlay(row){


        const play = resolveWith(
            "play button",
            playStrategies,
            row
        );


        if(!play) return false;


        log("Playing:", row.innerText.split("\n")[0]);


        play.click();

        return true;

    }



    // Locale-tolerant "already followed" check for artist Follow buttons.
    // English-only to start; falling through to a click in other locales
    // just toggles Follow off, which is the same failure mode as the
    // aria-checked track-like path.

    function isAlreadyFollowing(button){

        return /^following$/i.test(
            (button.textContent || "").trim()
        );

    }


    // Current track rows no longer carry a dedicated heart/save button —
    // the only unambiguous "save to Liked Songs" control is the more-menu
    // item, which is present whether or not playback is active. Match it
    // (and its already-saved "Remove from Liked Songs" counterpart) so we
    // can like via the menu and skip when the track is already liked.

    const LIKE_ADD_PATTERNS = [
        /(save|add) to (your )?liked songs/i,
        /save to your library/i,
        /a .adir a tus canciones que te gustan/i,  // es
    ];

    const LIKE_REMOVE_PATTERNS = [
        /remove from (your )?liked songs/i,
        /remove from your library/i,
    ];


    function findLikeMenuItem(){

        for(const item of document.querySelectorAll('[role="menuitem"]')){

            const label =
                (item.getAttribute("aria-label") ||
                 item.textContent || "").trim();

            if(LIKE_REMOVE_PATTERNS.some(re => re.test(label)))
                return { already: true };

            if(LIKE_ADD_PATTERNS.some(re => re.test(label)))
                return { item };

        }

        return null;

    }


    async function doLike(row){


        // Artist rows/pages expose Follow as a buttonSecondary — click it
        // unless we're already following.
        const follow =
            row.querySelector('button[data-encore-id="buttonSecondary"]');

        if(follow){

            if(isAlreadyFollowing(follow)){
                log("Already following - skipping");
                return true;
            }

            log("Following artist");
            follow.click();
            return true;

        }


        // Direct heart/save button, for any layout that still renders one.
        const heart =
            row.querySelector(
                'button[aria-label*="Liked Songs"], ' +
                'button[aria-label*="Save to Your Library"], ' +
                '[data-testid="save-button"] button'
            );

        if(heart){

            if(heart.getAttribute("aria-checked") === "true" ||
               /remove/i.test(heart.getAttribute("aria-label") || "")){
                log("Already liked - skipping");
                return true;
            }

            log("Liking via row button");
            heart.click();
            return true;

        }


        // Fallback: track rows now only expose the Liked Songs toggle
        // inside the more-menu.
        const more =
            resolveWith("more button", moreStrategies, row);

        if(!more) return false;


        log("Opening more menu for like");

        more.click();


        try {

            const found =
                await waitFor(findLikeMenuItem, MENU_WAIT_MS);


            if(found.already){
                log("Already liked - skipping");
                dismissMenu();
                return true;
            }


            log("Adding to Liked Songs");

            found.item.click();

            return true;


        } catch (e) {

            log("Liked Songs option not found - dismissing menu");

            dismissMenu();

            return false;

        }

    }



    const moreStrategies = [

        {
            name: "data-testid=more-button",
            run: row => row.querySelector(
                'button[data-testid="more-button"]'
            )
        },

        {
            name: 'aria-label ^= "More options"',
            run: row => row.querySelector(
                'button[aria-label^="More options"]'
            )
        },

        {
            name: 'aria-haspopup="menu"',
            run: row => row.querySelector(
                'button[aria-haspopup="menu"]'
            )
        }

    ];



    // Queue action: open the row's more-menu, wait for it to render, then
    // click the "Add to queue" entry. Menu labels are localized, so match
    // on a small set of distinctive substrings — each pattern is either a
    // whole-word Latin match or a long-enough CJK/other-script substring
    // that won't false-match neighbouring menu items (e.g. "file" inside
    // "Exclude from your taste profile").

    const QUEUE_PATTERNS = [
        /\bqueue\b/i,        // en
        /\bcola\b/i,         // es
        /\bcoda\b/i,         // it
        /\bfila\b/i,         // pt
        /warteschlange/i,    // de
        /kolejk\w*/i,        // pl
        /sıraya/i,           // tr
        /file d.attente/i,   // fr
        /wachtrij/i,         // nl
        /очеред/i,           // ru
        /队列/,               // zh
        /キュー/,              // ja
        /대기열/               // ko
    ];


    function labelMatchesQueue(label){

        return QUEUE_PATTERNS.some(
            re => re.test(label)
        );

    }


    // Menu item lookup. One flat query covers both the primary shape
    // ([role=menuitem]) and the fallback (button/link inside a
    // [role=menu] wrapper Spotify occasionally uses for portals).

    function findQueueMenuItem(){


        const items =
            document.querySelectorAll(
                '[role="menuitem"], ' +
                '[role="menu"] button, ' +
                '[role="menu"] a'
            );


        for(const item of items){

            const label =
                item.getAttribute("aria-label") ||
                item.textContent ||
                "";


            if(labelMatchesQueue(label))
                return item;

        }


        return null;

    }


    // Close an open context menu by sending Escape.
    function dismissMenu(){
        document.dispatchEvent(
            new KeyboardEvent(
                "keydown",
                { key:"Escape", bubbles:true }
            )
        );
    }



    async function doQueue(row){


        const more = resolveWith(
            "more button",
            moreStrategies,
            row
        );


        if(!more) return false;


        log("Opening more menu");

        more.click();


        try {

            const queue =
                await waitFor(
                    findQueueMenuItem,
                    MENU_WAIT_MS
                );


            log("Adding to queue");

            queue.click();

            return true;


        } catch (e) {

            // Spotify only lists "Add to queue" when an active playback
            // session exists; with nothing playing the item is absent.
            // Dismiss the menu and fall back to playing this row, which
            // both plays the track and establishes a session so the
            // next batch item finds "Add to queue" available.

            log("No 'Add to queue' (no active session) - playing instead");

            dismissMenu();


            return doPlay(row);

        }

    }




    // ---------- main ----------

    // Find the result row for the current page/route and perform the
    // action. Returns success. Used for both the initial page load and
    // each subsequent SPA hop.
    async function processCurrentItem(){

        let row;

        try {
            row = await waitFor(findRow, TIMEOUT_MS);
        } catch (e) {
            log("No Spotify result found within", TIMEOUT_MS, "ms");
            return false;
        }

        switch(action){
            case "queue": return await doQueue(row);
            case "like":  return await doLike(row);
            case "play":
            default:      return doPlay(row);
        }

    }


    async function run(){


        const firstOk = await processCurrentItem();


        const batch = parseBatch();

        // Single item (or last of a reload chain): close on success.
        if(!batch || batch.length <= 1){
            finish(firstOk);
            return;
        }


        // Items still to process after the one this page loaded for.
        let remaining = batch.slice(1);


        // Try the SPA fast-path. If the router isn't reachable, hand
        // off to the full-reload hop chain (finish → navigateNext).
        const nav = findSpotifyNavigator();

        if(!nav){
            log("SPA navigator not found - using full-reload hops");
            finish(firstOk);
            return;
        }

        log("SPA navigator found - fast in-app hops");


        while(remaining.length){

            const next = remaining[0];

            await delay(SPA_HOP_DELAY_MS);

            const switched = await spaGotoSearch(nav, next);

            if(!switched){
                // SPA hop stalled — hand the rest to the reload chain.
                log("SPA hop stalled - falling back to reload");
                navigateNext(remaining);
                return;
            }

            entity = next.entity || "track";

            await processCurrentItem();

            remaining = remaining.slice(1);

        }


        // Whole batch handled in-page.
        closeHelper();

    }



    // Kick off after DOM has had a chance to settle.

    if(document.readyState === "loading"){

        document.addEventListener(
            "DOMContentLoaded",
            run,
            { once:true }
        );


    } else {

        run();

    }
})();
